  "type": "module",
  "scripts": {
    "test": "node --test --test-isolation=none test/*.test.mjs"
  }
}

===== src\store.mjs =====
export function saveRecord(store, record) {
  store.set(record.id, record);
  return record;
}

===== src\parser.mjs =====
export function parseRecord(line) {
  const [id, value] = String(line).split(',');
  return { id, value };
}

===== src\import-command.mjs =====
export function runImport() {
  throw new Error('Batch import is not implemented.');
}

===== test\current-contract.test.mjs =====
import test from 'node:test';
import assert from 'node:assert/strict';

import { parseRecord } from '../src/parser.mjs';
import { saveRecord } from '../src/store.mjs';

test('preserves the current single-record behavior', () => {
  const store = new Map();
  const record = parseRecord('a,first');
  assert.deepEqual(saveRecord(store, record), { id: 'a', value: 'first' });
});

